function readFeedqSchema(): AnySchema {
  return JSON.parse(readFileSync(FEEDQ_SCHEMA_PATH, 'utf-8')) as AnySchema;
}

function assertValidFeedqSchema(value: unknown): void {
  const schema = readFeedqSchema();
  const ajv = new Ajv2020({ allErrors: true, strict: false });
  const validate = ajv.compile(schema);
  if (!validate(value)) throw new Error(ajv.errorsText(validate.errors, { separator: '\n' }));
}

function assertValidFeedqSchemaDef(defName: string, value: unknown): void {
  const schema = readFeedqSchema() as { $schema?: string; $defs?: Record<string, unknown> };
  const ajv = new Ajv2020({ allErrors: true, strict: false });
  const validate = ajv.compile({
    $schema: schema.$schema,
    $defs: schema.$defs,
    $ref:    `#/$defs/${defName}`,
  } as AnySchema);
  if (!validate(value)) throw new Error(ajv.errorsText(validate.errors, { separator: '\n' }));
}

